'use strict';
// Independent deterministic review of the optional coffee guide. Reuses the
// existing full DOM test double, production state callbacks and core RAF driver.
// This is not browser, perceptual, or production-publication QA.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),vm=require('node:vm');
const {fixture:makeFixture,near,clone,stable}=require('./review-process-invariants.cjs');
const root=path.resolve(__dirname,'..'),coffeePath=path.join(root,'dist/scenes/coffee.js');
const source=fs.readFileSync(coffeePath,'utf8'),baselinePath=process.env.COFFEE_BASELINE||path.join(__dirname,'baselines/162e4f5a9b923809450e6c4062540dba139543da/dist/scenes/coffee.js');
const baseline=fs.existsSync(baselinePath)?fs.readFileSync(baselinePath,'utf8'):null;
const PREWET=.672,FLOW_SECONDS=4.928,results=[],evidence=[];
function fixture(id,options={}){
 const f=makeFixture(id,{...options,setup:false,sourceOverride:options.sourceOverride||source});
 // Include the actual shell destinations, not just the no-dock setup fallback.
 const d=f.document,proto=Object.getPrototypeOf(d);proto.focus=function(){d.activeElement=this;};proto.scrollIntoView=function(){};proto.contains=function(node){return this===node||this.children.some(child=>child.contains(node));};
 const dock=d.createElement('section');dock.className='play-dock';const primary=d.createElement('div');primary.id='btns';primary.className='actions';
 for(const config of f.cfg.buttons){const b=d.createElement('button');b.className='act';b.textContent=config.label;b.onclick=()=>{config.onClick(f.s,f.ui);f.ui.invalidate();};primary.append(b);}
 const extras=d.createElement('div');extras.className='dock-extras';dock.append(primary,extras);d.body.append(dock);
 f.dock=dock;f.primary=primary;f.extras=extras;
 const mount=f.mount;f.mount=()=>{const ob=mount();const host=ob.panel.parentElement;host.remove();extras.append(host);return ob;};
 if(options.setup)f.mount();return f;
}

function test(name,fn){try{fn();results.push({name,ok:true});}catch(error){results.push({name,ok:false,error:error.stack});}}
const physicalKeys=['phase','beans','ground','filter','filterT','cup','cupT','takeT','fill','milk','milkT','brewT','pressure','t','targetFill','brewTarget','brewDuration','brewPaused','run','made'];
const physical=f=>Object.fromEntries(physicalKeys.map(k=>[k,f.s[k]]));
function prepare(f){for(const action of ['beans','grind','filter','cup']){f.action(action);f.finish();}assert.equal(f.s.phase,'locked');assert.equal(f.s.cup,true);}
function start(f,target=1){prepare(f);f.action(target===.5?'targetHalf':'targetFull');f.finish();f.action('brew');assert.equal(f.s.phase,'brewing');}
function assertReadOnly(f){const before=f.snapshot(),read=f.observation();assert.equal(f.snapshot(),before);for(let i=0;i<4;i++){f.observation();f.ui.observation?.update();}assert.equal(f.snapshot(),before,'reads and redraws cannot advance guide or mechanism');return read;}
function verifyGeometry(f){const observation=assertReadOnly(f),markup=f.render();assert(!/NaN|undefined|Infinity/.test(markup));assert.equal(observation.readouts.find(x=>x.label==='咖啡液量').value,Math.round(f.s.fill*100)+'%');assert.equal(observation.readouts.find(x=>x.label==='示意压力').value,Math.round(f.s.pressure*100)+'%');assert.equal(markup.includes('data-observe-part="coffee-extraction"'),f.s.phase==='brewing'&&f.s.t>PREWET,'stream visibility follows actual brew clock');assert(!observation.active.some(id=>/tank|heater|pump/.test(id)),'never highlight unmodeled internals');return observation;}
function finishCup(f,{milk=false}={}){if(milk){f.action('milk');f.finish();assert.equal(f.s.milk,1);}f.action('collect');f.finish();assert.equal(f.s.phase,'collected');assert.equal(f.s.made,1);assert.equal(f.s.cup,false);}

function commonTests(){
 test('the original main-model geometry source is unchanged',()=>{const a=source.indexOf(' function scene(s,m)'),b=source.indexOf(' const observation=',a);assert(a>=0&&b>a);assert.equal(crypto.createHash('sha256').update(source.slice(a,b)).digest('hex'),'10fba725b6c08c49dfa7a314072fa9294632445044d58b7082b9ba9847039c5f');});
 test('free play still uses eight primary actions and never auto-pauses at wetting',()=>{for(const target of [.5,1]){const f=fixture('coffee',{setup:true});assert.equal(f.cfg.buttons.length,8);assert.equal(f.ui.observation.panel.open,false);start(f,target);f.tick(.8);assert.equal(f.s.brewPaused,false);assert(f.s.t>PREWET);assert(f.s.fill>0);verifyGeometry(f);f.finish();near(f.s.fill,target);assert.equal(f.s.phase,'ready');assert.equal(f.s.pressure,0);finishCup(f,{milk:target===1});stable(f);}});
 test('merely opening the parent observer preserves continuous free play',()=>{const f=fixture('coffee',{setup:true});f.toggle(f.ui.observation.panel,true);start(f);f.tick(.8);assert.equal(f.s.brewPaused,false);assert(f.s.fill>0);f.finish();near(f.s.fill,1);stable(f);});
 if(baseline)test('baseline and candidate produce identical free-play physical states and artwork',()=>{for(const target of [.5,1]){const a=fixture('coffee',{setup:true}),b=fixture('coffee',{setup:true,sourceOverride:baseline});const compare=(label,render=false)=>{assert.deepEqual(physical(a),physical(b),label);if(render)for(const [yaw,pitch] of [[0,15],[45,35.264],[135,65],[225,20],[315,60]])assert.equal(a.render(yaw,pitch),b.render(yaw,pitch),label+' artwork '+yaw+'/'+pitch);};compare('initial',true);for(const act of ['beans','grind','filter','cup',target===.5?'targetHalf':'targetFull','brew','milk','collect','reset']){a.action(act);b.action(act);compare(act+' begins');let n=0;while((a.pending||b.pending)&&n++<2000){a.frame();b.frame();compare(act+' frame '+n,n%17===0);}assert(n<2000);compare(act+' rests',true);}assert.equal(a.s.made,1);}});
 else results.push({name:'baseline physical-state and artwork comparison',ok:true,skipped:true,reason:'Set COFFEE_BASELINE to an original pre-guide coffee.js. The pinned main-model source hash still verifies unchanged geometry without it.'});
}

// Guide-specific state, controls and interaction checks are below.
function nodes(f){const panel=f.ui.observation.panel,fold=f.document.querySelector('.coffee-guide');assert(fold);return {panel,fold,go:fold.querySelector('.coffee-guide-go'),exit:fold.querySelector('.coffee-guide-exit'),title:fold.querySelector('.coffee-guide-title'),reason:fold.querySelector('.coffee-guide-reason'),look:fold.querySelector('.coffee-guide-look'),dots:fold.querySelectorAll('.coffee-guide-route span'),pause:panel.querySelector('.coffee-process button'),hold:fold.querySelector('.coffee-guide-hold')};}
function openGuide(f){const n=nodes(f);f.toggle(n.panel,true);f.toggle(n.fold,true);f.finish();assert.equal(f.s.guideEnabled,true);return n;}
function readGuide(f){const before=f.snapshot(),read=clone(f.cfg.guide.read(f.s));assert.equal(f.snapshot(),before,'guide read is derived only');return read;}
function sync(f,n){const g=readGuide(f);f.ui.observation.update();assert.equal(n.title.textContent,(g.completed?'完成':String(g.index+1)+' / 7')+' · '+g.title);assert.equal(n.reason.textContent,g.text);assert.equal(n.go.textContent,g.label);assert.equal(n.go.getAttribute('aria-disabled'),String(g.busy));assert.equal(n.go.disabled,false,'go retains native focus while business guard enforces busy');assert.equal(n.look.textContent,'看这里：'+g.look);for(let i=0;i<7;i++){assert.equal(n.dots[i].dataset.done,String(g.completed||i<g.index));assert.equal(n.dots[i].getAttribute('aria-current'),i===g.index?'step':null);}verifyGeometry(f);return g;}
function checkpoint(f,target=1){start(f,target);f.finish();assert.equal(f.s.phase,'brewing');assert.equal(f.s.brewPaused,true);assert.equal(f.s.guideHold,true);assert.equal(f.s.guideWetSeen,true);near(f.s.t,PREWET,'exact checkpoint',0);assert.equal(f.s.fill,0);near(f.s.pressure,1,'built illustrative pressure');}
function guideTests(){
 test('guide moves the original card and free controls to the dock without clones, then restores them',()=>{const f=fixture('coffee',{setup:true}),n=nodes(f),home=n.fold.parentElement,buttons=[...f.primary.children];assert.equal(f.primary.parentElement,f.dock);assert.equal(n.fold.parentElement,home);f.toggle(n.panel,true);f.toggle(n.fold,true);f.finish();const free=f.dock.querySelector('.coffee-free-controls');assert(free);assert.equal(n.fold.parentElement,f.dock);assert.equal(free.open,false);assert.equal(f.primary.parentElement,free);assert.equal(f.dock.classList.contains('coffee-guiding'),true);assert.equal(f.document.querySelectorAll('#btns').length,1);assert.equal(f.document.querySelectorAll('.coffee-guide').length,1);assert.equal(home.querySelector('.observation-live').hidden,true);assert.equal(home.querySelector('.observation-intro').hidden,true);n.go.focus();n.go.click();f.frame();assert.equal(f.document.activeElement,n.go);assert.equal(n.go.disabled,false);assert.equal(n.go.getAttribute('aria-disabled'),'true');assert.equal(n.hold.hidden,false);const run=f.s.run;n.go.click();f.frame();assert.equal(f.s.run,run,'aria-disabled busy go is guarded');n.hold.focus();n.hold.click();assert.equal(f.document.activeElement,n.go,'pause hands focus to visible resume control');f.finish();assert.equal(f.s.brewPaused,true);assert.equal(n.hold.hidden,true);assert.equal(n.go.getAttribute('aria-disabled'),'false');n.exit.click();f.finish();assert.equal(f.s.brewPaused,false);assert.equal(f.s.phase,'beans');assert.equal(n.fold.parentElement,home);assert.equal(f.primary.parentElement,f.dock);assert.deepEqual(f.primary.children,buttons);assert.equal(f.dock.classList.contains('coffee-guiding'),false);assert.equal(home.querySelector('.observation-live').hidden,false);assert.equal(home.querySelector('.observation-intro').hidden,false);assert.equal(f.document.activeElement,n.fold.querySelector('summary'));for(let i=0;i<12;i++){f.toggle(n.fold,true);free.open=true;n.fold.querySelector('summary').focus();f.toggle(n.fold,false);f.finish();assert.equal(f.document.activeElement,n.fold.querySelector('summary'),'native collapse retains relocated summary focus');assert.equal(free.open,false);assert.equal(f.document.querySelectorAll('#btns').length,1);assert.equal(f.document.querySelectorAll('.coffee-guide').length,1);assert.equal(f.primary.parentElement,f.dock);assert.deepEqual(f.primary.children,buttons);}f.toggle(n.fold,true);f.toggle(n.panel,false);f.finish();assert.equal(f.primary.parentElement,f.dock);assert.equal(n.fold.parentElement,home);assert.equal(n.fold.open,false);assert.equal(f.s.guideEnabled,false);});
 test('guide is independently collapsed, opt-in, seven-stage and derives all UI from state',()=>{const f=fixture('coffee',{setup:true}),n=nodes(f);assert.equal(n.panel.open,false);assert.equal(n.fold.open,false);assert.equal(f.s.guideEnabled,false);assert.equal(f.s.guideWetSeen,false);assert.equal(f.s.guideHold,false);assert.equal(n.dots.length,7);f.toggle(n.panel,true);f.finish();assert.equal(f.s.guideEnabled,false);assert.equal(n.fold.open,false);f.toggle(n.fold,true);f.finish();assert.equal(f.s.guideEnabled,true);assert.equal(sync(f,n).index,0);stable(f);});
 test('guide next dispatches the real actions and ignores repeated clicks while each animation is busy',()=>{const f=fixture('coffee',{setup:true}),n=openGuide(f),sequence=[['empty','adding','beans',0,1],['beans','grinding','ground',1,2],['ground','locking','locked',2,3],['locked','placing','locked',3,4]];for(const [before,during,after,index,next] of sequence){assert.equal(f.s.phase,before);assert.equal(sync(f,n).index,index);const run=f.s.run;n.go.click();assert.equal(f.s.phase,during);assert.equal(f.s.run,run+1);const initial=physical(f);for(let j=0;j<20;j++)f.action('guideNext');assert.deepEqual(physical(f),initial,'repeated go is inert '+during);f.tick(.12);sync(f,n);f.finish();assert.equal(f.s.phase,after);assert.equal(sync(f,n).index,next);}n.go.click();f.finish();near(f.s.t,PREWET,'go reaches exact wetting');assert.equal(sync(f,n).index,4);assert.equal(n.go.getAttribute('aria-disabled'),'false');assert.match(n.reason.textContent,/尚未新增/);assert.match(n.reason.textContent,/不是实机停泵/);const run=f.s.run;n.go.click();assert.equal(f.s.run,run);f.frame();assert.equal(sync(f,n).index,5);f.finish();assert.equal(sync(f,n).index,6);assert.equal(f.s.made,0);n.go.click();f.tick(.16);assert.equal(f.s.made,0);sync(f,n);f.finish();assert.equal(sync(f,n).index,7);assert.equal(f.s.made,1);assert.equal(f.s.cup,false);n.go.click();f.finish();assert.equal(f.s.guideEnabled,true);assert.equal(sync(f,n).index,0);assert.equal(f.s.made,1);});
 test('half and full cups freeze at the same exact physical prewet boundary with no elapsed-time catchup',()=>{for(const target of [.5,1])for(const dt of [.04,.053,.06]){const f=fixture('coffee',{setup:true}),n=openGuide(f);start(f,target);let frames=0;while(f.pending&&frames++<100)f.frame(dt);assert(frames<100);near(f.s.t,PREWET,'wet boundary',0);assert.equal(f.s.fill,0);assert.equal(f.s.brewPaused,true);assert.equal(f.s.guideHold,true);near(f.s.brewT,PREWET/(PREWET+FLOW_SECONDS*target));sync(f,n);stable(f,60);const run=f.s.run;n.go.click();f.frame(dt);near(f.s.t,PREWET+dt,'single resumed delta');assert.equal(f.s.run,run);assert.equal(f.s.guideHold,false);assert.equal(f.s.guideWetSeen,true);assert(f.s.fill>0);sync(f,n);f.finish();near(f.s.fill,target);assert.equal(f.s.phase,'ready');assert.equal(f.s.brewPaused,false);evidence.push({target,frameDelta:dt,checkpoint:PREWET,fill:f.s.fill,frames});}});
 test('one auto-pause per brew survives repeated enter exit and repeated resume',()=>{const f=fixture('coffee',{setup:true}),n=openGuide(f);checkpoint(f,.5);for(let i=0;i<30;i++){f.action('guideEnter');assert.equal(f.s.brewPaused,true);assert.equal(f.s.t,PREWET);}f.action('guideNext');const run=f.s.run;for(let i=0;i<30;i++){f.action('guideNext');assert.equal(f.s.run,run);assert.equal(f.s.brewPaused,false);}f.frame();const t=f.s.t,fill=f.s.fill;for(let i=0;i<30;i++){f.action('guideExit');f.action('guideEnter');}assert.equal(f.s.t,t);assert.equal(f.s.fill,fill);f.frame();near(f.s.t,t+.04);assert.equal(f.s.brewPaused,false);f.finish();near(f.s.fill,.5);assert.equal(f.s.phase,'ready');sync(f,n);});
 test('manual observation pause freezes every guided moving phase with exactly one resumed driver',()=>{for(const phase of ['adding','grinding','locking','placing','brewing','milk','taking']){const f=fixture('coffee',{setup:true}),n=openGuide(f);for(const act of ['beans','grind','filter','cup','brew','milk','collect']){f.action(act);if(f.s.phase===phase){f.tick(.12);break;}f.finish();if(f.s.guideHold){f.action('guideNext');f.finish();}}assert.equal(f.s.phase,phase);const run=f.s.run;f.action('pause');f.finish();assert.equal(f.s.brewPaused,true);const t=f.s.t;sync(f,n);stable(f,15);f.action('guideNext');assert.equal(f.s.brewPaused,false);f.frame();near(f.s.t,t+.04,phase+' resumes once');assert.equal(f.s.run,run);if(f.s.phase==='brewing'){f.finish();if(f.s.guideHold){f.action('guideNext');f.finish();}}else f.finish();assert.equal(f.s.brewPaused,false);assert.equal(f.pending,0);}});
 test('exit by action, nested close, parent close or exit button preserves cup and resumes held work once',()=>{for(const exit of ['action','fold','panel','button'])for(const when of ['before','checkpoint','flow']){const f=fixture('coffee',{setup:true}),n=openGuide(f);start(f,.5);if(when==='before'){f.tick(.24);f.action('pause');f.finish();}else{f.finish();if(when==='flow'){f.action('guideNext');f.tick(.36);f.action('pause');f.finish();}}const before=physical(f),run=f.s.run;if(exit==='action')f.action('guideExit');if(exit==='fold')f.toggle(n.fold,false);if(exit==='panel')f.toggle(n.panel,false);if(exit==='button')n.exit.click();assert.equal(f.s.guideEnabled,false);assert.equal(f.s.brewPaused,false);assert.equal(f.s.guideHold,false);for(const key of ['cup','fill','filter','ground','milk','t','run','made'])assert.equal(f.s[key],before[key],exit+' preserves '+key);f.frame();near(f.s.t,before.t+.04,exit+' one resumed frame');assert.equal(f.s.run,run);f.finish();assert.equal(f.s.phase,'ready');near(f.s.fill,.5);f.toggle(n.panel,true);f.toggle(n.fold,true);f.finish();assert.equal(f.s.phase,'ready');assert.equal(f.s.fill,.5);assert.equal(f.s.made,0);assert.equal(sync(f,n).index,6);}});
 test('entering at existing preparation, prewet, flow, ready, milk and collection never restarts or rewinds',()=>{for(const at of ['beans','prewet','flow','ready','milk','taking','collected']){const f=fixture('coffee',{setup:true});if(at==='beans'){f.action('beans');f.finish();}else{start(f);if(at==='prewet')f.tick(.24);else if(at==='flow')f.tick(1.2);else{f.finish();if(at==='milk'){f.action('milk');f.tick(.4);}if(at==='taking'||at==='collected'){f.action('collect');at==='taking'?f.tick(.24):f.finish();}}}const p=physical(f),n=nodes(f);f.toggle(n.panel,true);f.toggle(n.fold,true);assert.deepEqual(physical(f),p,at+' opening changes no mechanics');sync(f,n);if(at==='flow'){f.finish();assert.equal(f.s.brewPaused,false);assert.equal(f.s.phase,'ready');}if(at==='prewet'){f.finish();assert.equal(f.s.brewPaused,true);near(f.s.t,PREWET);}if(at==='collected'){f.finish();assert.equal(f.s.made,1);assert.equal(f.pending,0);}}});
 test('stopping before or during wetting permits restart, while a partial cup is preserved and collectable',()=>{for(const at of [.2,PREWET,.72,1.24]){const f=fixture('coffee',{setup:true}),n=openGuide(f);start(f,.5);at===PREWET?f.finish():f.tick(Math.min(at,.64));if(at>PREWET){f.finish();f.action('guideNext');f.tick(at-PREWET);}f.action('brew');f.finish();const amount=f.s.fill;assert.equal(f.s.phase,'ready');assert.equal(f.s.brewPaused,false);assert.equal(f.s.guideHold,false);assert.equal(f.s.pressure,0);const step=sync(f,n);assert.equal(step.completed,false);if(amount<.02){assert.equal(step.action,'brew');assert.equal(step.index,4);const run=f.s.run;f.action('guideNext');assert.equal(f.s.run,run+1);assert.equal(f.s.fill,amount);f.finish();near(f.s.t,PREWET,'new run checkpoint');assert.equal(f.s.fill,amount);assert.equal(f.s.guideHold,true);assert.match(sync(f,n).text,/尚未新增/);f.action('guideNext');f.finish();near(f.s.fill,.5);}else{assert.equal(step.action,'collect');assert.equal(step.index,6);assert(!/目标.*完成|全部完成/.test(step.text));f.action('guideNext');f.finish();assert.equal(f.s.made,1);near(f.s.fill,amount);}}});
 test('reset from guided paused or unpaused motion retires stale work and preserves only made count and mode',()=>{for(const when of ['adding','prewet','checkpoint','flow','milk','taking'])for(const pause of [false,true]){const f=fixture('coffee',{setup:true});openGuide(f);if(when==='adding'){f.action('beans');f.tick(.2);}else{start(f,.5);if(when==='prewet')f.tick(.2);else{f.finish();if(when!=='checkpoint'){f.action('guideNext');when==='flow'?f.tick(.4):f.finish();if(when==='milk'){f.action('milk');f.tick(.5);}if(when==='taking'){f.action('collect');f.tick(.2);}}}}if(pause&&!f.s.brewPaused)f.action('pause');f.action('reset');f.finish();assert.equal(f.s.guideEnabled,true);assert.equal(f.s.guideHold,false);assert.equal(f.s.guideWetSeen,false);assert.equal(f.s.brewPaused,false);assert.equal(f.s.phase,'empty');assert.equal(f.s.fill,0);assert.equal(f.s.made,0);stable(f,20);checkpoint(f,.5);f.action('guideNext');f.finish();finishCup(f);assert.equal(f.s.made,1);}});
 test('invalid or out-of-order actions never create guide progress, duplicate cups or a new animation',()=>{const f=fixture('coffee',{setup:true}),n=openGuide(f);for(const bad of ['grind','filter','cup','brew','milk','collect','pause']){const before=physical(f);f.action(bad);assert.deepEqual(physical(f),before,bad+' rejected from empty');f.finish();assert.equal(sync(f,n).index,0);}checkpoint(f);for(const bad of ['beans','grind','filter','cup','milk','collect','targetHalf','targetFull']){const before=f.snapshot();f.action(bad);f.finish();assert.equal(f.snapshot(),before,bad+' preserves held cup');assert.equal(sync(f,n).index,4);}f.action('guideNext');f.finish();f.action('milk');f.action('milk');f.finish();assert.equal(f.s.milk,1);f.action('collect');f.action('collect');f.action('cup');f.finish();assert.equal(f.s.made,1);assert.equal(sync(f,n).index,7);f.action('guideExit');const before=physical(f);for(let i=0;i<10;i++)f.action('guideNext');f.finish();assert.deepEqual(physical(f),before,'guide next outside mode is inert');});
 test('half/full milk and collection stay optional real actions with consistent final amount and count',()=>{for(const target of [.5,1])for(const milk of [false,true]){const f=fixture('coffee',{setup:true}),n=openGuide(f);checkpoint(f,target);f.action('guideNext');f.finish();near(f.s.fill,target);if(milk){f.action('milk');f.tick(1);assert.equal(sync(f,n).index,6);assert.equal(f.s.fill,target);assert.equal(f.s.made,0);f.finish();assert.equal(f.s.milk,1);}f.action('guideNext');f.tick(.4);assert.equal(f.s.made,0);assert.equal(sync(f,n).index,6);f.finish();assert.equal(sync(f,n).completed,true);assert.equal(f.s.made,1);near(f.s.fill,target);assert.equal(f.s.milk,milk?1:0);stable(f);}});
 test('quarter speed follows identical physical states and the same exact wetting checkpoint',()=>{const a=fixture('coffee',{setup:true}),b=fixture('coffee',{setup:true});openGuide(a);openGuide(b);start(a);start(b);b.ui.simulationRate=.25;for(let i=0;i<12;i++){a.frame();for(let j=0;j<4;j++)b.frame();near(a.s.t,b.s.t);near(a.s.pressure,b.s.pressure);near(a.s.fill,b.s.fill);}a.finish();b.finish();near(a.s.t,PREWET);near(b.s.t,PREWET);assert.equal(a.s.brewPaused,true);assert.equal(b.s.brewPaused,true);a.action('guideNext');b.action('guideNext');for(let i=0;i<20;i++){a.frame();for(let j=0;j<4;j++)b.frame();near(a.s.t,b.s.t);near(a.s.fill,b.s.fill);near(a.s.pressure,b.s.pressure);}a.finish();b.finish();near(a.s.fill,1);near(b.s.fill,1);});
 test('hidden document cancels RAF with no catchup or guide advancement, then resumes correctly',()=>{for(const when of ['prewet','checkpoint','flow','grinding']){const f=fixture('coffee',{setup:true}),n=openGuide(f);if(when==='grinding'){f.action('beans');f.finish();f.action('grind');f.tick(.4);}else{start(f);if(when==='prewet')f.tick(.2);else{f.finish();if(when==='flow'){f.action('guideNext');f.tick(.4);}}}f.document.hidden=true;f.document.emit('visibilitychange');assert.equal(f.pending,0);const before=f.snapshot(),frames=f.frames,step=readGuide(f);f.tick(45);assert.equal(f.snapshot(),before);assert.equal(f.frames,frames);assert.deepEqual(readGuide(f),step);f.document.hidden=false;f.document.emit('visibilitychange');f.frame();if(when==='checkpoint'){near(f.s.t,PREWET);assert.equal(f.s.brewPaused,true);assert.equal(f.pending,0);}else near(f.s.t,JSON.parse(before).t+.04,'visible resume one dt');sync(f,n);f.action('guideExit');f.finish();assert.equal(f.s.brewPaused,false);assert.equal(f.pending,0);}});
 test('current stage, physical highlights and readouts share state at all seven causal stages',()=>{const f=fixture('coffee',{setup:true}),n=openGuide(f),expect=(index,active)=>{const step=sync(f,n),ob=f.observation();assert.equal(step.index,index);for(const id of active)assert(ob.active.includes(id),'stage '+index+' highlights '+id);};expect(0,['coffee-hopper']);f.action('guideNext');f.finish();expect(1,['coffee-hopper','coffee-grinder']);f.action('guideNext');f.tick(.8);expect(1,['coffee-hopper','coffee-grinder','coffee-filter']);f.finish();expect(2,['coffee-filter']);f.action('guideNext');f.tick(.4);expect(2,['coffee-filter','coffee-head']);f.finish();expect(3,['coffee-cup']);f.action('guideNext');f.finish();expect(4,['coffee-head','coffee-cup']);f.action('guideNext');f.finish();expect(4,['coffee-pressure','coffee-filter']);f.action('guideNext');f.frame();expect(5,['coffee-pressure','coffee-extraction','coffee-cup']);f.finish();expect(6,['coffee-cup']);f.action('guideNext');f.finish();expect(7,['coffee-hopper']);stable(f);});
}

async function audioTests(){
 const text=fs.readFileSync(path.join(__dirname,'audit-mechanical-audio.cjs'),'utf8').split('const results=[];')[0],box={require,console,__dirname};vm.createContext(box);vm.runInContext(text+'\nglobalThis.fixture=make;',box);
 const testAsync=async(name,fn)=>{try{await fn();results.push({name,ok:true});}catch(error){results.push({name,ok:false,error:error.stack});}};
 await testAsync('guided pause does not manufacture audio consent and silences/resumes one real grinder pump or pour loop',async()=>{
  for(const phase of ['grinding','brewing','milk'])for(const enabled of [false,true]){const f=fixture('coffee',{setup:true});openGuide(f);const audio=box.fixture();audio.api.attach('coffee');const original=f.ui.render;f.ui.render=()=>{original();audio.api.update('coffee',f.s);};if(phase==='grinding'){f.action('beans');f.finish();f.action('grind');f.tick(.4);}else{checkpoint(f,.5);f.action('guideNext');if(phase==='brewing')f.tick(.4);else{f.finish();f.action('milk');f.tick(1.2);}}assert.equal(f.s.phase,phase);if(enabled){await audio.enable();assert.equal(audio.panel().dataset.audioLoop,{grinding:'grinder',brewing:'pump',milk:'pour'}[phase]);}else assert.equal(audio.contexts.length,0);f.action('pause');f.finish();assert.equal(audio.panel().dataset.audioLoop,'none');if(enabled){const c=audio.contexts[0];c.tick(.3);assert.equal(c.nodes.filter(n=>n.started&&!n.ended).length,0);const count=c.nodes.length;for(let i=0;i<20;i++)audio.api.update('coffee',f.s);assert.equal(c.nodes.length,count);}else assert.equal(audio.contexts.length,0);f.action('guideExit');f.frame();if(enabled){assert.equal(audio.panel().dataset.audioLoop,{grinding:'grinder',brewing:'pump',milk:'pour'}[phase]);assert.equal(audio.contexts[0].nodes.filter(n=>n.started&&!n.ended).length,phase==='milk'?1:2);audio.event('pagehide');assert.equal(audio.api.enabled,false);}else assert.equal(audio.contexts.length,0);f.finish();}
 });
}
(async()=>{
commonTests();
guideTests();
await audioTests();
const report={candidateSha256:crypto.createHash('sha256').update(source).digest('hex'),passed:results.filter(r=>r.ok&&!r.skipped).length,total:results.filter(r=>!r.skipped).length,skipped:results.filter(r=>r.skipped).length,evidence,limits:'Production callbacks and actual core RAF; mocked DOM. No browser, perceptual/audio listening, Git changes, or publication.',results};
console.log(JSON.stringify(report,null,2));if(report.passed!==report.total)process.exitCode=1;
})();
